content.content:
1	/* ================================================================
2	   城市浮生记 (City Life Story) — 全局样式
3	   设计参考: Notion Light + Kindle Green Mode + Zen Garden
4	   主题: 鲜亮绿色护眼 — 奶油白底色 + 鼠尾草绿强调，减少暗沉，长时间游玩不疲劳
5	   参考研究:
6	   - Notion Light — 奶油白底 + 柔和边框 + 绿色交互反馈
7	   - Kindle Green — 淡绿底护眼，高对比文字
8	   - 禅意花园 — 鼠尾草绿/薄荷/翠绿渐变，自然感
9	   ================================================================ */
10	
11	/* ====== CSS 变量 / 主题 (鲜亮绿色护眼) ====== */
12	:root {
13	  --bg-primary: #f5f1e8;
14	  --bg-secondary: #faf7f0;
15	  --bg-card: #ffffff;
16	  --bg-card-hover: #f0f7f0;
17	  --bg-sidebar: #faf7f0;
18	  --bg-input: #f0ede4;
19	
20	  --border: #d8d5c8;
21	  --border-light: #c5d5c0;
22	
23	  --text-primary: #2c3328;
24	  --text-secondary: #5a6652;
25	  --text-muted: #8a9680;
26	
27	  --accent: #4a9e5c;
28	  --accent-glow: rgba(74, 158, 92, 0.12);
29	  --accent-hover: #3a8048;
30	
31	  --success: #4a9e5c;
32	  --success-bg: rgba(74, 158, 92, 0.1);
33	  --danger: #c4553d;
34	  --danger-bg: rgba(196, 85, 61, 0.08);
35	  --warning: #c49a3a;
36	  --warning-bg: rgba(196, 154, 58, 0.1);
37	  --info: #5a8ab4;
38	
39	  --hair-color: #7ab8d8;
40	  --mental-color: #b8a0d4;
41	  --kpi-color: #d4a840;
42	  --risk-color: #c4553d;
43	  --physique-color: #c4803a;
44	  --intelligence-color: #5a8ab4;
45	  --agility-color: #5aaa5a;
46	  --mental-attrs-color: #9b74b8;
47	
48	  --font-mono: "Consolas", "Courier New", monospace;
49	  --font-sans:
50	    -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC",
51	    "Microsoft YaHei", sans-serif;
52	
53	  --radius-sm: 4px;
54	  --radius-md: 8px;
55	  --radius-lg: 12px;
56	  --radius-xl: 16px;
57	
58	  --sidebar-width: 280px;
59	  --header-height: 48px;
60	  --transition: 0.2s ease;
61	}
62	
63	/* ====== Reset ====== */
64	*,
65	*::before,
66	*::after {
67	  box-sizing: border-box;
68	  margin: 0;
69	  padding: 0;
70	}
71	
72	html,
73	body {
74	  height: 100%;
75	  overflow: hidden;
76	}
77	
78	body {
79	  font-family: var(--font-sans);
80	  font-size: 14px;
81	  line-height: 1.5;
82	  color: var(--text-primary);
83	  background: var(--bg-primary);
84	  -webkit-font-smoothing: antialiased;
85	}
86	
87	/* ====== Scrollbar ====== */
88	::-webkit-scrollbar {
89	  width: 6px;
90	  height: 6px;
91	}
92	::-webkit-scrollbar-track {
93	  background: transparent;
94	}
95	::-webkit-scrollbar-thumb {
96	  background: var(--border-light);
97	  border-radius: 3px;
98	}
99	::-webkit-scrollbar-thumb:hover {
100	  background: var(--text-muted);
101	}
102	
103	/* ====== App Layout (CSS Grid) ====== */
104	#app {
105	  display: grid;
106	  grid-template-rows: var(--header-height) 1fr;
107	  grid-template-columns: var(--sidebar-width) 1fr;
108	  grid-template-areas:
109	    "header header"
110	    "sidebar main";
111	  height: 100vh;
112	  max-height: 100vh;
113	}
114	
115	/* ====== Header ====== */
116	#header {
117	  grid-area: header;
118	  display: flex;
119	  align-items: center;
120	  justify-content: space-between;
121	  padding: 0 16px;
122	  background: var(--bg-secondary);
123	  border-bottom: 1px solid var(--border);
124	  z-index: 100;
125	}
126	
127	.header-left {
128	  display: flex;
129	  align-items: center;
130	  gap: 12px;
131	}
132	
133	.header-logo {
134	  font-size: 18px;
135	  font-weight: 700;
136	  color: var(--accent);
137	  letter-spacing: 0.5px;
138	}
139	
140	.header-logo span {
141	  color: var(--text-secondary);
142	  font-size: 12px;
143	  font-weight: 400;
144	  margin-left: 6px;
145	}
146	
147	.header-stats {
148	  display: flex;
149	  align-items: center;
150	  gap: 20px;
151	  font-size: 13px;
152	}
153	
154	.header-stat {
155	  display: flex;
156	  align-items: center;
157	  gap: 6px;
158	}
159	
160	.header-stat .label {
161	  color: var(--text-muted);
162	  font-size: 11px;
163	}
164	
165	.header-stat .value {
166	  color: var(--text-primary);
167	  font-weight: 600;
168	}
169	
170	.header-stat .value.cash {
171	  color: var(--success);
172	}
173	
174	.header-stat .value.age {
175	  color: var(--warning);
176	}
177	
178	.header-actions {
179	  display: flex;
180	  align-items: center;
181	  gap: 8px;
182	}
183	
184	/* ====== Sidebar ====== */
185	#sidebar {
186	  grid-area: sidebar;
187	  background: var(--bg-sidebar);
188	  border-right: 1px solid var(--border);
189	  overflow-y: auto;
190	  overflow-x: hidden;
191	  padding: 16px 12px;
192	  display: flex;
193	  flex-direction: column;
194	  gap: 16px;
195	}
196	
197	.sidebar-section {
198	  background: var(--bg-card);
199	  border-radius: var(--radius-md);
200	  padding: 12px;
201	  border: 1px solid transparent;
202	}
203	
204	.sidebar-section h3 {
205	  font-size: 11px;
206	  text-transform: uppercase;
207	  letter-spacing: 1px;
208	  color: var(--text-muted);
209	  margin-bottom: 10px;
210	  font-weight: 600;
211	}
212	
213	/* --- 属性条 --- */
214	.stat-row {
215	  display: flex;
216	  align-items: center;
217	  gap: 8px;
218	  margin-bottom: 6px;
219	}
220	
221	.stat-label {
222	  width: 65px;
223	  font-size: 12px;
224	  color: var(--text-secondary);
225	  text-align: right;
226	  flex-shrink: 0;
227	}
228	
229	.stat-bar-wrap {
230	  flex: 1;
231	  height: 16px;
232	  background: rgba(255, 255, 255, 0.05);
233	  border-radius: var(--radius-sm);
234	  overflow: hidden;
235	  position: relative;
236	}
237	
238	.stat-bar {
239	  height: 100%;
240	  border-radius: var(--radius-sm);
241	  transition: width 0.4s ease;
242	  position: relative;
243	}
244	
245	/* 数值变化闪烁动画 */
246	.stat-bar.flash {
247	  animation: statFlash 0.6s ease;
248	}
249	
250	@keyframes statFlash {
251	  0% {
252	    filter: brightness(1);
253	  }
254	  50% {
255	    filter: brightness(2.5);
256	  }
257	  100% {
258	    filter: brightness(1);
259	  }
260	}
261	
262	.stat-bar.hair {
263	  background: linear-gradient(90deg, #5a90b4, var(--hair-color));
264	}
265	.stat-bar.dignity {
266	  background: linear-gradient(90deg, #9a7abf, var(--mental-color));
267	}
268	.stat-bar.kpi {
269	  background: linear-gradient(90deg, #d4a830, var(--kpi-color));
270	}
271	.stat-bar.risk {
272	  background: linear-gradient(90deg, #c05848, var(--risk-color));
273	}
274	.stat-bar.physique {
275	  background: linear-gradient(90deg, #c48030, var(--physique-color));
276	}
277	.stat-bar.intelligence {
278	  background: linear-gradient(90deg, #4a88b4, var(--intelligence-color));
279	}
280	.stat-bar.agility {
281	  background: linear-gradient(90deg, #4a9a40, var(--agility-color));
282	}
283	.stat-bar.mental-bar {
284	  background: linear-gradient(90deg, #8a5ea8, var(--mental-attrs-color));
285	}
286	.stat-bar.hunger {
287	  background: linear-gradient(90deg, #d4a020, #e8c040);
288	}
289	.stat-bar.fatigue {
290	  background: linear-gradient(90deg, #8a9080, #b0b8a0);
291	}
292	.stat-bar.hygiene {
293	  background: linear-gradient(90deg, #3a8a84, #5ac4b0);
294	}
295	.stat-bar.happiness {
296	  background: linear-gradient(90deg, #d46050, #e88070);
297	}
298	.stat-bar.health {
299	  background: linear-gradient(90deg, #e06048, #4aae5a);
300	}
301	.stat-bar.fame {
302	  background: linear-gradient(90deg, #9a5ea8, #d4a030);
303	}
304	.stat-bar.ap-bar {
305	  background: linear-gradient(90deg, #4a9e5c, #5ac060, #40b850);
306	}
307	
308	.stat-value {
309	  width: 48px;
310	  font-size: 11px;
311	  color: var(--text-muted);
312	  text-align: right;
313	  flex-shrink: 0;
314	  font-family: var(--font-mono);
315	}
316	
317	/* --- 地点 --- */
318	.location-display {
319	  display: flex;
320	  align-items: center;
321	  justify-content: space-between;
322	  margin-bottom: 8px;
323	}
324	
325	.location-name {
326	  font-size: 14px;
327	  font-weight: 600;
328	  color: var(--accent);
329	}
330	
331	.location-desc {
332	  font-size: 11px;
333	  color: var(--text-muted);
334	}
335	
336	/* ====== Main Content ====== */
337	#main {
338	  grid-area: main;
339	  display: flex;
340	  flex-direction: column;
341	  overflow: hidden;
342	  background: var(--bg-primary);
343	}
344	
345	/* --- Tab Bar --- */
346	#tab-bar {
347	  display: flex;
348	  background: var(--bg-secondary);
349	  border-bottom: 1px solid var(--border);
350	  padding: 0 12px;
351	  flex-shrink: 0;
352	}
353	
354	.tab-btn {
355	  padding: 10px 20px;
356	  font-size: 13px;
357	  color: var(--text-muted);
358	  background: none;
359	  border: none;
360	  border-bottom: 2px solid transparent;
361	  cursor: pointer;
362	  transition: all var(--transition);
363	  font-family: var(--font-sans);
364	}
365	
366	.tab-btn:hover {
367	  color: var(--text-primary);
368	  background: rgba(255, 255, 255, 0.03);
369	}
370	
371	.tab-btn.active {
372	  color: var(--accent);
373	  border-bottom-color: var(--accent);
374	}
375	
376	/* --- Content Area --- */
377	#content-area {
378	  flex: 1;
379	  overflow-y: auto;
380	  padding: 16px;
381	  display: flex;
382	  flex-direction: column;
383	  gap: 16px;
384	}
385	
386	/* --- Time Slot Indicator --- */
387	#time-slot-indicator {
388	  display: flex;
389	  align-items: center;
390	  gap: 8px;
391	  padding: 8px 16px;
392	  background: var(--bg-card);
393	  border-radius: var(--radius-md);
394	  font-size: 13px;
395	  flex-shrink: 0;
396	}
397	
398	.time-slot-badge {
399	  padding: 2px 10px;
400	  border-radius: var(--radius-sm);
401	  font-size: 11px;
402	  font-weight: 600;
403	}
404	
405	.time-slot-badge.morning {
406	  background: rgba(243, 156, 18, 0.2);
407	  color: var(--warning);
408	}
409	.time-slot-badge.afternoon {
410	  background: rgba(74, 158, 92, 0.2);
411	  color: var(--warning);
412	}
413	.time-slot-badge.evening {
414	  background: rgba(142, 68, 173, 0.2);
415	  color: #9b59b6;
416	}
417	
418	/* --- Action Cards Grid --- */
419	.action-cards {
420	  display: grid;
421	  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
422	  gap: 10px;
423	}
424	
425	.action-card {
426	  background: var(--bg-card);
427	  border: 1px solid var(--border);
428	  border-radius: var(--radius-md);
429	  padding: 14px;
430	  cursor: pointer;
431	  transition: all var(--transition);
432	}
433	
434	.action-card:hover {
435	  background: var(--bg-card-hover);
436	  border-color: var(--accent);
437	  transform: translateY(-1px);
438	  box-shadow: 0 4px 12px var(--accent-glow);
439	}
440	
441	.action-card.disabled {
442	  opacity: 0.4;
443	  cursor: not-allowed;
444	}
445	
446	.action-card.disabled:hover {
447	  border-color: var(--border);
448	  transform: none;
449	  box-shadow: none;
450	}
451	
452	.action-card .card-icon {
453	  font-size: 24px;
454	  margin-bottom: 6px;
455	}
456	
457	.action-card .card-title {
458	  font-size: 14px;
459	  font-weight: 600;
460	  color: var(--text-primary);
461	  margin-bottom: 4px;
462	}
463	
464	.action-card .card-desc {
465	  font-size: 11px;
466	  color: var(--text-muted);
467	  margin-bottom: 8px;
468	  line-height: 1.4;
469	}
470	
471	.action-card .card-meta {
472	  display: flex;
473	  justify-content: space-between;
474	  align-items: center;
475	  font-size: 11px;
476	}
477	
478	.card-meta .ap-cost {
479	  color: var(--warning);
480	  font-weight: 600;
481	  font-size: 10px;
482	  padding: 2px 6px;
483	  border-radius: 3px;
484	  background: rgba(243, 156, 18, 0.12);
485	  border: 1px solid rgba(243, 156, 18, 0.25);
486	}
487	
488	.card-meta .pay-estimate {
489	  color: var(--success);
490	  font-weight: 600;
491	}
492	
493	.card-meta .cost-estimate {
494	  color: var(--danger);
495	  font-weight: 600;
496	}
497	
498	.card-meta .slot-tag {
499	  padding: 1px 6px;
500	  border-radius: var(--radius-sm);
501	  font-size: 10px;
502	  background: var(--accent-glow);
503	  color: var(--accent);
504	}
505	
506	.card-meta .req-fail {
507	  color: var(--danger);
508	  font-size: 10px;
509	}
510	
511	/* --- Message Log --- */
512	#message-log {
513	  background: var(--bg-card);
514	  border: 1px solid var(--border);
515	  border-radius: var(--radius-md);
516	  padding: 12px;
517	  max-height: 250px;
518	  overflow-y: auto;
519	  flex-shrink: 0;
520	}
521	
522	#message-log h3 {
523	  font-size: 11px;
524	  text-transform: uppercase;
525	  letter-spacing: 1px;
526	  color: var(--text-muted);
527	  margin-bottom: 8px;
528	  font-weight: 600;
529	}
530	
531	.log-entry {
532	  padding: 3px 0;
533	  font-size: 12px;
534	  border-bottom: 1px solid rgba(255, 255, 255, 0.03);
535	  animation: fadeIn 0.3s ease;
536	}
537	
538	.log-entry .log-day {
539	  color: var(--text-muted);
540	  font-size: 10px;
541	  margin-right: 8px;
542	  font-family: var(--font-mono);
543	}
544	
545	.log-entry.info {
546	  color: var(--text-secondary);
547	}
548	.log-entry.success {
549	  color: var(--success);
550	}
551	.log-entry.danger {
552	  color: var(--danger);
553	}
554	.log-entry.warning {
555	  color: var(--warning);
556	}
557	.log-entry.event {
558	  color: var(--accent);
559	  font-weight: 600;
560	}
561	
562	/* --- Inventory Grid --- */
563	.inventory-grid {
564	  display: grid;
565	  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
566	  gap: 8px;
567	}
568	
569	.inventory-item {
570	  background: var(--bg-card);
571	  border: 1px solid var(--border);
572	  border-radius: var(--radius-sm);
573	  padding: 10px;
574	  font-size: 12px;
575	}
576	
577	.inventory-item .item-name {
578	  font-weight: 600;
579	  color: var(--text-primary);
580	}
581	
582	.inventory-item .item-qty {
583	  color: var(--text-muted);
584	  font-size: 10px;
585	}
586	
587	.inventory-item .item-effects {
588	  color: var(--success);
589	  font-size: 10px;
590	}
591	
592	/* ====== Buttons ====== */
593	.btn {
594	  display: inline-flex;
595	  align-items: center;
596	  justify-content: center;
597	  gap: 6px;
598	  padding: 8px 16px;
599	  font-size: 13px;
600	  font-family: var(--font-sans);
601	  font-weight: 500;
602	  border: 1px solid var(--border);
603	  border-radius: var(--radius-sm);
604	  cursor: pointer;
605	  transition: all var(--transition);
606	  background: var(--bg-card);
607	  color: var(--text-primary);
608	  white-space: nowrap;
609	}
610	
611	.btn:hover {
612	  background: var(--bg-card-hover);
613	  border-color: var(--border-light);
614	}
615	
616	.btn:active {
617	  transform: scale(0.97);
618	}
619	
620	.btn-primary {
621	  background: var(--accent);
622	  border-color: var(--accent);
623	  color: #fff;
624	}
625	
626	.btn-primary:hover {
627	  background: var(--accent-hover);
628	}
629	
630	.btn-success {
631	  background: var(--success);
632	  border-color: var(--success);
633	  color: #fff;
634	}
635	
636	.btn-danger {
637	  background: var(--danger);
638	  border-color: var(--danger);
639	  color: #fff;
640	}
641	
642	.btn-sm {
643	  padding: 4px 10px;
644	  font-size: 11px;
645	}
646	
647	.btn-lg {
648	  padding: 12px 24px;
649	  font-size: 15px;
650	  border-radius: var(--radius-md);
651	}
652	
653	/* ====== Modal ====== */
654	.modal-overlay {
655	  position: fixed;
656	  top: 0;
657	  left: 0;
658	  right: 0;
659	  bottom: 0;
660	  background: rgba(0, 0, 0, 0.7);
661	  display: flex;
662	  align-items: center;
663	  justify-content: center;
664	  z-index: 1000;
665	  animation: fadeIn 0.2s ease;
666	}
667	
668	.modal-box {
669	  background: var(--bg-secondary);
670	  border: 1px solid var(--border);
671	  border-radius: var(--radius-lg);
672	  padding: 24px;
673	  min-width: 360px;
674	  max-width: 520px;
675	  max-height: 80vh;
676	  overflow-y: auto;
677	  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
678	  animation: slideUp 0.2s ease;
679	}
680	
681	.modal-box h2 {
682	  font-size: 18px;
683	  margin-bottom: 12px;
684	  color: var(--text-primary);
685	}
686	
687	.modal-box p {
688	  font-size: 13px;
689	  color: var(--text-secondary);
690	  margin-bottom: 16px;
691	  line-height: 1.6;
692	}
693	
694	.modal-actions {
695	  display: flex;
696	  gap: 8px;
697	  justify-content: flex-end;
698	}
699	
700	/* ====== Game Over / Victory Screen ====== */
701	.end-screen {
702	  text-align: center;
703	}
704	
705	.end-screen .end-icon {
706	  font-size: 64px;
707	  margin-bottom: 16px;
708	}
709	
710	.end-screen .end-title {
711	  font-size: 28px;
712	  font-weight: 700;
713	  margin-bottom: 8px;
714	}
715	
716	.end-screen .end-subtitle {
717	  font-size: 14px;
718	  color: var(--text-secondary);
719	  margin-bottom: 20px;
720	}
721	
722	.end-screen.victory .end-title {
723	  color: var(--success);
724	}
725	.end-screen.defeat .end-title {
726	  color: var(--danger);
727	}
728	
729	/* --- Stats Summary Table --- */
730	.stats-summary {
731	  width: 100%;
732	  border-collapse: collapse;
733	  margin: 16px 0;
734	}
735	
736	.stats-summary td {
737	  padding: 6px 12px;
738	  font-size: 13px;
739	  border-bottom: 1px solid var(--border);
740	}
741	
742	.stats-summary td:first-child {
743	  color: var(--text-muted);
744	}
745	
746	.stats-summary td:last-child {
747	  text-align: right;
748	  font-weight: 600;
749	}
750	
751	/* ====== News Banner ====== */
752	.news-banner {
753	  background: linear-gradient(135deg, var(--bg-card), rgba(74, 158, 92, 0.08));
754	  border: 1px solid var(--accent);
755	  border-left: 3px solid var(--accent);
756	  border-radius: var(--radius-sm);
757	  padding: 10px 14px;
758	  font-size: 12px;
759	  color: var(--accent);
760	  flex-shrink: 0;
761	}
762	
763	.news-banner .news-icon {
764	  margin-right: 6px;
765	}
766	
767	/* ====== Event Modal (Random Story Event) ====== */
768	.event-box {
769	  min-width: 380px;
770	  max-width: 540px;
771	  border-top: 4px solid var(--accent);
772	  background: linear-gradient(180deg, var(--bg-secondary), var(--bg-card));
773	}
774	
775	.event-header {
776	  display: flex;
777	  align-items: center;
778	  gap: 12px;
779	  margin-bottom: 14px;
780	  padding-bottom: 12px;
781	  border-bottom: 1px solid var(--border);
782	}
783	
784	.event-icon {
785	  font-size: 40px;
786	  width: 56px;
787	  height: 56px;
788	  display: flex;
789	  align-items: center;
790	  justify-content: center;
791	  background: radial-gradient(circle, rgba(74, 158, 92, 0.15), transparent);
792	  border-radius: 50%;
793	  flex-shrink: 0;
794	}
795	
796	.event-title {
797	  font-size: 18px;
798	  color: var(--accent);
799	  margin: 0;
800	}
801	
802	.event-story {
803	  font-size: 13px;
804	  color: var(--text-primary);
805	  line-height: 1.7;
806	  margin-bottom: 16px;
807	  padding: 12px 14px;
808	  background: var(--bg-card);
809	  border-left: 3px solid var(--accent);
810	  border-radius: var(--radius-sm);
811	}
812	
813	.event-choices {
814	  display: flex;
815	  flex-direction: column;
816	  gap: 8px;
817	}
818	
819	.event-choice {
820	  display: block;
821	  width: 100%;
822	  text-align: left;
823	  background: var(--bg-card);
824	  border: 1px solid var(--border);
825	  border-radius: var(--radius-md);
826	  padding: 10px 14px;
827	  color: var(--text-primary);
828	  font-size: 13px;
829	  cursor: pointer;
830	  transition: all 0.15s ease;
831	  position: relative;
832	}
833	
834	.event-choice:hover:not(.disabled) {
835	  background: var(--bg-card-hover, rgba(74, 158, 92, 0.08));
836	  border-color: var(--accent);
837	  transform: translateX(2px);
838	}
839	
840	.event-choice.disabled {
841	  opacity: 0.4;
842	  cursor: not-allowed;
843	}
844	
845	.event-choice .choice-main {
846	  font-weight: 600;
847	  color: var(--text-primary);
848	}
849	
850	.event-choice .choice-hint {
851	  font-size: 11px;
852	  color: var(--text-muted);
853	  margin-top: 3px;
854	}
855	
856	/* 弹窗进入动画 */
857	@keyframes eventPop {
858	  0% {
859	    transform: scale(0.85) translateY(-20px);
860	    opacity: 0;
861	  }
862	  100% {
863	    transform: scale(1) translateY(0);
864	    opacity: 1;
865	  }
866	}
867	
868	.event-overlay,
869	.modal-overlay.event-modal {
870	  animation: fadeIn 0.2s ease;
871	}
872	
873	.event-overlay .modal-box,
874	.modal-overlay.event-modal .modal-box {
875	  animation: eventPop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
876	}
877	
878	/* ====== Utility Classes ====== */
879	.text-success {
880	  color: var(--success);
881	}
882	.text-danger {
883	  color: var(--danger);
884	}
885	.text-warning {
886	  color: var(--warning);
887	}
888	.text-accent {
889	  color: var(--accent);
890	}
891	.text-muted {
892	  color: var(--text-muted);
893	}
894	.text-sm {
895	  font-size: 11px;
896	}
897	.text-lg {
898	  font-size: 16px;
899	}
900	.font-mono {
901	  font-family: var(--font-mono);
902	}
903	
904	.flex {
905	  display: flex;
906	}
907	.flex-col {
908	  flex-direction: column;
909	}
910	.items-center {
911	  align-items: center;
912	}
913	.justify-between {
914	  justify-content: space-between;
915	}
916	.gap-2 {
917	  gap: 8px;
918	}
919	.gap-4 {
920	  gap: 16px;
921	}
922	.mt-2 {
923	  margin-top: 8px;
924	}
925	.mt-4 {
926	  margin-top: 16px;
927	}
928	.mb-2 {
929	  margin-bottom: 8px;
930	}
931	
932	/* ====== Animations ====== */
933	@keyframes fadeIn {
934	  from {
935	    opacity: 0;
936	  }
937	  to {
938	    opacity: 1;
939	  }
940	}
941	
942	@keyframes slideUp {
943	  from {
944	    opacity: 0;
945	    transform: translateY(16px);
946	  }
947	  to {
948	    opacity: 1;
949	    transform: translateY(0);
950	  }
951	}
952	
953	@keyframes pulse {
954	  0%,
955	  100% {
956	    opacity: 1;
957	  }
958	  50% {
959	    opacity: 0.5;
960	  }
961	}
962	
963	.pulse {
964	  animation: pulse 2s infinite;
965	}
966	
967	/* ====== Welcome Screen ====== */
968	.welcome-screen {
969	  display: flex;
970	  flex-direction: column;
971	  align-items: center;
972	  justify-content: center;
973	  height: 100vh;
974	  gap: 24px;
975	  text-align: center;
976	}
977	
978	.welcome-title {
979	  font-size: 36px;
980	  font-weight: 700;
981	  color: var(--accent);
982	  letter-spacing: 1px;
983	}
984	
985	.welcome-subtitle {
986	  font-size: 14px;
987	  color: var(--text-muted);
988	  max-width: 400px;
989	  line-height: 1.6;
990	}
991	
992	.welcome-buttons {
993	  display: flex;
994	  gap: 12px;
995	}
996	
997	/* ====== Tab Content Panels ====== */
998	.tab-panel {
999	  display: none;
1000	}
1001	
1002	.tab-panel.active {
1003	  display: block;
1004	}
1005	
1006	/* ====== City Map ====== */
1007	.city-map {
1008	  position: relative;
1009	}
1010	
1011	.city-map .map-node {
1012	  animation: mapFadeIn 0.4s ease backwards;
1013	}
1014	
1015	.city-map .map-node:nth-child(1) {
1016	  animation-delay: 0.02s;
1017	}
1018	.city-map .map-node:nth-child(2) {
1019	  animation-delay: 0.04s;
1020	}
1021	.city-map .map-node:nth-child(3) {
1022	  animation-delay: 0.06s;
1023	}
1024	.city-map .map-node:nth-child(4) {
1025	  animation-delay: 0.08s;
1026	}
1027	.city-map .map-node:nth-child(5) {
1028	  animation-delay: 0.1s;
1029	}
1030	.city-map .map-node:nth-child(6) {
1031	  animation-delay: 0.12s;
1032	}
1033	.city-map .map-node:nth-child(7) {
1034	  animation-delay: 0.14s;
1035	}
1036	.city-map .map-node:nth-child(8) {
1037	  animation-delay: 0.16s;
1038	}
1039	.city-map .map-node:nth-child(9) {
1040	  animation-delay: 0.18s;
1041	}
1042	.city-map .map-node:nth-child(10) {
1043	  animation-delay: 0.2s;
1044	}
1045	.city-map .map-node:nth-child(11) {
1046	  animation-delay: 0.22s;
1047	}
1048	
1049	@keyframes mapFadeIn {
1050	  from {
1051	    opacity: 0;
1052	    transform: translate(-50%, -50%) scale(0.8);
1053	  }
1054	  to {
1055	    opacity: 1;
1056	    transform: translate(-50%, -50%) scale(1);
1057	  }
1058	}
1059	
1060	/* Nearby locations sidebar widget */
1061	.nearby-loc-item {
1062	  cursor: pointer;
1063	  transition: all 0.2s ease;
1064	}
1065	
1066	.nearby-loc-item:hover {
1067	  border-color: var(--accent) !important;
1068	  background: var(--bg-card-hover) !important;
1069	  transform: translateX(2px);
1070	}
1071	
1072	/* Location services badges area */
1073	#location-services {
1074	  min-height: 20px;
1075	}
1076	
1077	/* ====== Responsive: Mobile ====== */
1078	@media (max-width: 768px) {
1079	  #app {
1080	    grid-template-columns: 1fr;
1081	    grid-template-areas:
1082	      "header"
1083	      "main";
1084	  }
1085	
1086	  #sidebar {
1087	    position: fixed;
1088	    left: -100%;
1089	    top: var(--header-height);
1090	    bottom: 0;
1091	    width: 280px;
1092	    z-index: 200;
1093	    transition: left 0.3s ease;
1094	    box-shadow: 2px 0 8px rgba(0, 0, 0, 0.3);
1095	  }
1096	
1097	  #sidebar.open {
1098	    left: 0;
1099	  }
1100	
1101	  .action-cards {
1102	    grid-template-columns: 1fr;
1103	  }
1104	
1105	  .header-stats {
1106	    gap: 10px;
1107	  }
1108	
1109	  .header-stat .label {
1110	    display: none;
1111	  }
1112	
1113	  #mobile-menu-btn {
1114	    display: flex !important;
1115	  }
1116	
1117	  /* 地图节点放大，触控友好 */
1118	  .map-node {
1119	    min-width: 70px !important;
1120	    padding: 10px 14px !important;
1121	    font-size: 12px !important;
1122	  }
1123	
1124	  .city-map {
1125	    min-height: 400px !important;
1126	    padding: 12px !important;
1127	  }
1128	}
1129	
1130	#mobile-menu-btn {
1131	  display: none;
1132	  background: none;
1133	  border: none;
1134	  color: var(--text-primary);
1135	  font-size: 20px;
1136	  cursor: pointer;
1137	  padding: 4px;
1138	}
1139	
1140	@media (min-width: 769px) {
1141	  #mobile-menu-btn {
1142	    display: none !important;
1143	  }
1144	}
1145	
1146	/* ====== Tutorial System ====== */
1147	.tutorial-overlay .modal-box {
1148	  border: 2px solid var(--accent);
1149	  box-shadow: 0 0 40px rgba(102, 126, 234, 0.3);
1150	}
1151	.tutorial-box {
1152	  animation: fadeInUp 0.3s ease-out;
1153	}
1154	@keyframes tutorial-pulse {
1155	  0%,
1156	  100% {
1157	    box-shadow:
1158	      0 0 25px rgba(102, 126, 234, 0.5),
1159	      inset 0 0 25px rgba(102, 126, 234, 0.08);
1160	  }
1161	  50% {
1162	    box-shadow:
1163	      0 0 40px rgba(102, 126, 234, 0.8),
1164	      inset 0 0 40px rgba(102, 126, 234, 0.15);
1165	  }
1166	}
1167	@keyframes fadeInUp {
1168	  from {
1169	    opacity: 0;
1170	    transform: translateY(20px);
1171	  }
1172	  to {
1173	    opacity: 1;
1174	    transform: translateY(0);
1175	  }
1176	}
1177	
1178	/* 低行动力闪烁警告 */
1179	@keyframes ap-blink {
1180	  0%,
1181	  100% {
1182	    opacity: 1;
1183	  }
1184	  50% {
1185	    opacity: 0.3;
1186	  }
1187	}
1188	@keyframes ap-blink-border {
1189	  0%,
1190	  100% {
1191	    box-shadow: 0 0 12px rgba(255, 152, 0, 0.4);
1192	  }
1193	  50% {
1194	    box-shadow: 0 0 24px rgba(255, 152, 0, 0.8);
1195	  }
1196	}
