/* ================================================================
   城市浮生记 (City Life Story) — 全局样式
   设计参考: Notion Light + Kindle Green Mode + Zen Garden
   主题: 鲜亮绿色护眼 — 奶油白底色 + 鼠尾草绿强调，减少暗沉，长时间游玩不疲劳
   参考研究:
   - Notion Light — 奶油白底 + 柔和边框 + 绿色交互反馈
   - Kindle Green — 淡绿底护眼，高对比文字
   - 禅意花园 — 鼠尾草绿/薄荷/翠绿渐变，自然感
   ================================================================ */

/* ====== CSS 变量 / 主题 (鲜亮绿色护眼) ====== */
:root {
  --bg-primary: #f5f1e8;
  --bg-secondary: #faf7f0;
  --bg-card: #ffffff;
  --bg-card-hover: #f0f7f0;
  --bg-sidebar: #faf7f0;
  --bg-input: #f0ede4;

  --border: #d8d5c8;
  --border-light: #c5d5c0;

  --text-primary: #2c3328;
  --text-secondary: #5a6652;
  --text-muted: #8a9680;

  --accent: #4a9e5c;
  --accent-glow: rgba(74, 158, 92, 0.12);
  --accent-hover: #3a8048;

  --success: #4a9e5c;
  --success-bg: rgba(74, 158, 92, 0.1);
  --danger: #c4553d;
  --danger-bg: rgba(196, 85, 61, 0.08);
  --warning: #c49a3a;
  --warning-bg: rgba(196, 154, 58, 0.1);
  --info: #5a8ab4;

  --hair-color: #7ab8d8;
  --mental-color: #b8a0d4;
  --kpi-color: #d4a840;
  --risk-color: #c4553d;
  --physique-color: #c4803a;
  --intelligence-color: #5a8ab4;
  --agility-color: #5aaa5a;
  --mental-attrs-color: #9b74b8;

  --font-mono: "Consolas", "Courier New", monospace;
  --font-sans:
    -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC",
    "Microsoft YaHei", sans-serif;

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;

  --sidebar-width: 280px;
  --header-height: 48px;
  --transition: 0.2s ease;
}

/* ====== Reset ====== */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  height: 100%;
  overflow: hidden;
}

body {
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.5;
  color: var(--text-primary);
  background: var(--bg-primary);
  -webkit-font-smoothing: antialiased;
}

/* ====== Scrollbar ====== */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;

